import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

function Homepage() {

  const navigate = useNavigate();

  const [user, setUser] = useState(null);

  const [bookings, setBookings] = useState([]);

  const [loading, setLoading] = useState(true);

  useEffect(() => {

    // ดึง user จาก localStorage
    const userData =
      localStorage.getItem("user");

    // ถ้าไม่มี user -> กลับหน้า login
    if (!userData) {

      navigate("/");

      return;

    }

    // parse user
    const parsedUser =
      JSON.parse(userData);

    setUser(parsedUser);

    // ดึง booking ของ user
    const userId =
      parsedUser.user_id;

    if (userId) {

      axios
        .get(
          `http://localhost:5001/api/bookings/${userId}`
        )

        .then((response) => {

          setBookings(
            response.data.bookings || []
          );

        })

        .catch((error) => {

          console.log(
            "Error fetching bookings:",
            error
          );

        })

        .finally(() => {

          setLoading(false);

        });

    } else {

      setLoading(false);

    }

  }, [navigate]);

  // logout
  const logout = () => {

    localStorage.removeItem("token");

    localStorage.removeItem("user");

    navigate("/");

  };

  // loading
  if (!user) {

    return (

      <div
        className="
          d-flex
          justify-content-center
          align-items-center
        "
        style={{
          height: "100vh"
        }}
      >

        <h3>
          Loading...
        </h3>

      </div>

    );

  }

  return (

    <div
      style={{
        background: "#f1f5f9",
        minHeight: "100vh"
      }}
    >

      {/* NAVBAR */}
      <nav
        className="
          navbar
          navbar-expand-lg
          navbar-dark
          bg-primary
          shadow
        "
      >

        <div className="container">

          <span
            className="
              navbar-brand
              fw-bold
            "
          >
            CS Room Booking
          </span>

          <button
            className="
              btn
              btn-outline-light
            "
            onClick={logout}
          >
            Logout
          </button>

        </div>

      </nav>

      {/* CONTENT */}
      <div className="container py-4">

        <div className="row">

          {/* LEFT */}
          <div className="col-lg-8">

            {/* PROFILE */}
            <div
              className="
                card
                border-0
                shadow-sm
                mb-4
              "
              style={{
                borderRadius: "20px"
              }}
            >

              <div
                className="
                  card-header
                  bg-primary
                  text-white
                "
                style={{
                  borderRadius:
                    "20px 20px 0 0"
                }}
              >

                <h3 className="mb-0">

                  ยินดีต้อนรับ

                </h3>

              </div>

              <div className="card-body">

                <h4 className="mb-4">

                  {user.displayname_th ||
                    user.displayname_en}

                </h4>

                <p>

                  <strong>
                    เลขนักศึกษา:
                  </strong>

                  {" "}

                  {user.username ||
                    user.studentID ||
                    "-"}

                </p>

                <p>

                  <strong>
                    คณะ:
                  </strong>

                  {" "}

                  {user.faculty || "-"}

                </p>

                <p>

                  <strong>
                    สาขา:
                  </strong>

                  {" "}

                  {user.department || "-"}

                </p>

                <p>

                  <strong>
                    Email:
                  </strong>

                  {" "}

                  {user.email || "-"}

                </p>

              </div>

            </div>

            {/* BOOKINGS */}
            <div
              className="
                card
                border-0
                shadow-sm
              "
              style={{
                borderRadius: "20px"
              }}
            >

              <div
                className="
                  card-header
                  bg-success
                  text-white
                "
                style={{
                  borderRadius:
                    "20px 20px 0 0"
                }}
              >

                <h4 className="mb-0">

                  ประวัติการจองห้อง

                </h4>

              </div>

              <div className="card-body">

                {loading ? (

                  <div
                    className="
                      text-center
                      py-4
                    "
                  >

                    <div
                      className="
                        spinner-border
                        text-primary
                      "
                    ></div>

                    <p className="mt-3">

                      Loading bookings...

                    </p>

                  </div>

                ) : bookings.length > 0 ? (

                  <div className="table-responsive">

                    <table
                      className="
                        table
                        table-hover
                        align-middle
                      "
                    >

                      <thead>

                        <tr>

                          <th>
                            ห้อง
                          </th>

                          <th>
                            วันที่
                          </th>

                          <th>
                            เวลา
                          </th>

                          <th>
                            วัตถุประสงค์
                          </th>

                        </tr>

                      </thead>

                      <tbody>

                        {bookings.map(
                          (booking) => (

                          <tr
                            key={booking.id}
                          >

                            <td>
                              {booking.room}
                            </td>

                            <td>
                              {booking.date}
                            </td>

                            <td>

                              {booking.start_time}

                              {" - "}

                              {booking.end_time}

                            </td>

                            <td>

                              {booking.purpose ||
                                "-"}

                            </td>

                          </tr>

                        ))}

                      </tbody>

                    </table>

                  </div>

                ) : (

                  <div
                    className="
                      text-center
                      py-4
                    "
                  >

                    <h5>
                      ไม่มีการจองห้อง
                    </h5>

                  </div>

                )}

              </div>

            </div>

          </div>

          {/* RIGHT */}
          <div className="col-lg-4">

            <div
              className="
                card
                border-0
                shadow-sm
              "
              style={{
                borderRadius: "20px"
              }}
            >

              <div
                className="
                  card-header
                  bg-info
                  text-white
                "
                style={{
                  borderRadius:
                    "20px 20px 0 0"
                }}
              >

                <h4 className="mb-0">

                  เมนู

                </h4>

              </div>

              <div className="card-body">

                <button
                  className="
                    btn
                    btn-primary
                    w-100
                    mb-3
                  "
                  onClick={() =>
                    navigate("/booking")
                  }
                >

                  จองห้อง

                </button>

                <button
                  className="
                    btn
                    btn-success
                    w-100
                    mb-3
                  "
                >

                  ตารางห้อง

                </button>

                <button
                  className="
                    btn
                    btn-dark
                    w-100
                  "
                >

                  ประวัติทั้งหมด

                </button>

              </div>

            </div>

          </div>

        </div>

      </div>

    </div>

  );

}

export default Homepage;
